-- YouTube channel "Jul Ruz" (Yuliia): 29 public long videos as library sessions.
-- Videos stay on YouTube and play in the official embedded player; nothing is downloaded or re-uploaded.
-- Titles and lengths are taken from the channel as published; category, level, goals and body areas were
-- derived from the titles only and can be edited in the admin panel. Re-running is safe (slug conflict = skip).
alter table public.workouts disable trigger workouts_review_guard;

