alter table public.workouts enable trigger workouts_review_guard;

-- Programme from the channel's own series "День #1 … День #5"
alter table public.courses disable trigger courses_review_guard;
insert into public.courses (slug, title, description, cover_tone, level, access, language, author_id, published, published_at, review_status, kind)
values ('yoga-5-days',
  jsonb_build_object('en', '5 days of yoga', 'ru', '5 дней йоги', 'uk', '5 днів йоги'),
  jsonb_build_object('en', 'Yuliia''s five-day series from her YouTube channel, one session a day.', 'ru', 'Пятидневная серия Юлии с её YouTube-канала, одно занятие в день.', 'uk', 'П''ятиденна серія Юлії з її YouTube-каналу, одне заняття на день.'),
  'mint', 'beginner', 'free', 'ru', (select id from public.authors where id = 'yuliia'), true, now(), 'approved', 'program')
on conflict (slug) do nothing;
alter table public.courses enable trigger courses_review_guard;

do $body$
declare
  cid uuid;
  mid uuid;
begin
  select id into cid from public.courses where slug = 'yoga-5-days';
  if cid is null or exists (select 1 from public.course_modules where course_id = cid) then
    return;
  end if;
  insert into public.course_modules (course_id, title, position)
  values (cid, jsonb_build_object('en', 'Days 1–5', 'ru', 'Дни 1–5', 'uk', 'Дні 1–5'), 0)
  returning id into mid;
  insert into public.lessons (module_id, slug, title, duration_min, video, access, position, workout_id)
  select mid, 'day-' || d.n, jsonb_build_object('en', 'Day ' || d.n, 'ru', 'День ' || d.n, 'uk', 'День ' || d.n), w.duration_min, null, 'free', d.n, w.id
  from (values (1, 'yt-qoi27CDgjdk'), (2, 'yt-rNr65z2YFRo'), (3, 'yt-hRvell3y2LM'), (4, 'yt-iY3OL4DoZYw'), (5, 'yt-9oHfGZMHlzo')) as d(n, slug)
  join public.workouts w on w.slug = d.slug;
end;
$body$;
